mod solution;

fn main() {
    let cases = [
    (r#"[[1,3,5,7],[10,11,16,20],[23,30,34,60]]"#, r#"true"#),
    (r#"[[1,2],[3,4]]"#, r#"false"#),
    (r#"
[[1,2],[3,4]]
"#, r#"false"#),
    (r#"  
[[1,3,5,7],[10,11,16,20],[23,30,34,60]]
  "#, r#"true"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS matrix-binary-search");
}
